<script type="text/javascript" src="//cdn.jsdelivr.net/npm/slick-carousel@1.8.1/slick/slick.min.js"> </script>
<script>
    document.addEventListener("DOMContentLoaded", function () {
        const faqItems = document.querySelectorAll(".custom-faq-item");
        faqItems.forEach(function (item) {
            const question = item.querySelector(".custom-faq-question");
            const icon = question.querySelector("i");
            question.addEventListener("click", function (e) {
                e.preventDefault();
                const isActive = item.classList.contains("active");
                /* Close ALL */
                faqItems.forEach(function (faq) {
                    faq.classList.remove("active");
                    const faqIcon =
                        faq.querySelector(".custom-faq-question i");
                    if (faqIcon) {
                        faqIcon.classList.remove("icon-up-arrow");
                        faqIcon.classList.add("icon-down-arrow");
                    }
                });
                /* Open clicked */
                if (!isActive) {
                    item.classList.add("active");
                    icon.classList.remove("icon-down-arrow");
                    icon.classList.add("icon-up-arrow");
                }
            });
        });


        /* Next Script */
        const cards = Array.from( document.querySelectorAll(".trust-card") );
        const dots = Array.from( document.querySelectorAll(".trust-dot") );
        const prevBtn = document.querySelector(".trust-prev");
        const nextBtn = document.querySelector(".trust-next");
        let current = 0;

        /* =========================================================
        GET CIRCULAR INDEX
        ========================================================= */
        function getIndex(number) {
            const total = cards.length;
            return ( number + total ) % total;
        }

        /* =========================================================
        UPDATE TRUST SLIDER
        ========================================================= */
        function updateSlider() {
            /* Remove old classes */
            cards.forEach(function (card) {
                card.classList.remove(
                    "active",
                    "prev",
                    "next",
                    "prev-2",
                    "next-2"
                );
            });
            cards[current]
                .classList.add("active");

            cards[getIndex(current - 1)]
                .classList.add("prev");

            cards[getIndex(current + 1)]
                .classList.add("next");

            cards[getIndex(current - 2)]
                .classList.add("prev-2");

            cards[getIndex(current + 2)]
                .classList.add("next-2");

            dots.forEach(function (dot, index) {
                dot.classList.toggle(
                    "active",
                    index === current
                );
            });
        }

        function nextSlide() {
            current = getIndex(current + 1);
            updateSlider();
        }
        function previousSlide() {
            current = getIndex(current - 1);
            updateSlider();
        }
        nextBtn.addEventListener( "click", nextSlide );
        prevBtn.addEventListener( "click", previousSlide );
        dots.forEach(function (dot) {
            dot.addEventListener(
                "click",
                function () {
                    current =
                        parseInt(
                            this.dataset.slide,
                            10
                        );
                    updateSlider();
                }
            );
        });


        /* =========================================================
        TRUST SLIDER SWIPE
        ========================================================= */

        let startX = 0;
        const stage =
            document.querySelector(".trust-stage");
        stage.addEventListener(
            "touchstart",
            function (e) {
                startX =
                    e.touches[0].clientX;
            },
            { passive: true }
        );

        stage.addEventListener( "touchend", function (e) {
                const endX =
                    e.changedTouches[0].clientX;
                const difference =
                    startX - endX;
                if (Math.abs(difference) < 50) {
                    return;
                }
                if (difference > 0) {
                    nextSlide();
                } else {
                    previousSlide();
                }
            },
            { passive: true }
        );

        /* =========================================================
        TRUST SLIDER AUTO PLAY
        ========================================================= */

        let autoplay = setInterval( nextSlide, 5000 );
        function resetAutoplay() {
            clearInterval(autoplay);
            autoplay = setInterval( nextSlide, 20000 );
        }
        nextBtn.addEventListener( "click", resetAutoplay );
        prevBtn.addEventListener( "click", resetAutoplay );
        dots.forEach(function (dot) {
            dot.addEventListener(
                "click",
                resetAutoplay
            );
        });


        /* TRUST SLIDER INITIAL LOAD */

        updateSlider();
        /* TECHNOLOGY TABS */
        const techCards = document.querySelectorAll(".tech-small-card");
        const featureImage = document.getElementById("feature-image");
        const featureTitle = document.getElementById("feature-title");
        const featureDescription = document.getElementById("feature-description");
        /* TAB CONTENT */
        const tabData = {
            software: {
                image: "/wp-content/uploads/2026/08/Software-Development-ingigenetech.webp",
                title: "Software Development",
                description: "Indigenous technology solutions built for daily operations, reliable performance, team efficiency, and smooth scalability as business needs grow."
