        /* CHANGE TECHNOLOGY TAB */
        function changeTab(card) {
            const tabName = card.getAttribute("data-tab");
            const data = tabData[tabName];
            if (!data) {
                return;
            }
            techCards.forEach(function (item) {
                item.classList.remove("active");
            });
            card.classList.add("active");
            featureImage.style.opacity = "0";
            featureTitle.style.opacity = "0";
            featureDescription.style.opacity = "0";
            setTimeout(function () {
                featureImage.src = data.image;
                featureImage.alt = data.title;
                featureTitle.textContent = data.title;
                featureDescription.textContent = data.description;
                featureImage.style.opacity = "1";
                featureTitle.style.opacity = "1";
                featureDescription.style.opacity = "1";
            }, 180);
        }


        /* TECHNOLOGY TAB CLICK EVENTS */
        techCards.forEach(function (card) {
            card.addEventListener(
                "click",
                function (event) {
                    if (event.target.closest("a")) {
                        return;
                    }
                    changeTab(card);
                }
            );
        });


        /* TECHNOLOGY TAB INITIAL ACTIVE CARD */
        const activeCard = document.querySelector( ".tech-small-card.active" );
        if (activeCard) {
            const tabName = activeCard.getAttribute("data-tab");
            const data = tabData[tabName];
            if (data) {
                featureImage.src = data.image;
                featureImage.alt = data.title;
                featureTitle.textContent = data.title;
                featureDescription.textContent = data.description;
            }
        }


        /* INDUSTRY TABS */
        document.addEventListener(
            "click",
            function (event) {
                const tab =
                    event.target.closest(".industry-tab");
                if (!tab) {
                    return;
                }
                const wrapper =
                    tab.closest(".industries-wrapper");
                if (!wrapper) {
                    return;
                }
                const targetId =
                    tab.getAttribute("data-industry");
                wrapper
                    .querySelectorAll(".industry-tab")
                    .forEach(function (item) {
                        item.classList.remove("active");
                    });
                wrapper
                    .querySelectorAll(".industry-panel")
                    .forEach(function (panel) {
                        panel.classList.remove("active");
                    });
                tab.classList.add("active");
                const targetPanel =
                    wrapper.querySelector(
                        "#" + targetId
                    );
                if (targetPanel) {
                    targetPanel.classList.add("active");
                }
            }
        );


        /* Next Script */
        jQuery(document).ready(function ($) {
            function initMobileSlider(
                selector,
                slidesToShow,
                showNav = true
            ) {
                var $slider =
                    $(selector);
                if ($(window).width() < 992) {
                    if (!$slider.hasClass("slick-initialized")) {
                        $slider.slick({
                            slidesToShow: slidesToShow,
                            slidesToScroll: 1,
                            centerMode: false,
                            centerPadding: "0px",
                            dots: true,
                            arrows: showNav,
                            autoplay: true,
                            infinite: true,
                            prevArrow: '<button type="button" class="slick-prev" aria-label="slick prev"><i class="fas fa-chevron-left"></i></button>',
                            nextArrow: '<button type="button" class="slick-next" aria-label="slick next"><i class="fas fa-chevron-right"></i></button>'
                        });
                    }
                } else {
                    if ($slider.hasClass("slick-initialized")) {
                        $slider.slick("unslick");
                    }
                }
            }
            function runSliders() {
                initMobileSlider( ".mobile-view-slider", 1, true );
                initMobileSlider( ".mobile-two-slider", 2, true );
                initMobileSlider( ".mobile-three-slider", 3, false );
            }
            runSliders();
            $(window).on( "resize", function () { runSliders(); } );
        });


        /* Popup open/close is handled site-wide by itech-site.js. */
    });

    document.addEventListener("DOMContentLoaded", function () {
        document.addEventListener("click", function (event) {
            const button = event.target.closest(".indigene-tab-btn");
            if (!button) {
                return;
            }
            const section = button.closest("section");
            if (!section) {
                return;
            }
            const tabName = button.getAttribute("data-tab");
            if (!tabName) {
                return;
            }
            const buttons = section.querySelectorAll(".indigene-tab-btn");
            const contents = section.querySelectorAll(".indigene-tab-content");
            buttons.forEach(function (btn) {
                btn.classList.remove("active");
            });
            contents.forEach(function (content) {
                content.classList.remove("active");
            });
            button.classList.add("active");
            const target = section.querySelector(
                '.indigene-tab-content[id="' + CSS.escape(tabName) + '"]'
            );
            if (target) {
                target.classList.add("active");
            }
        });
    });
</script>
